import{_ as a,I as r,c as n,o as s,j as t,J as c,a5 as d,a as i}from"./chunks/framework.CUJoMJm2.js";const f=JSON.parse('{"title":"ADR 008: Enforce Reserved Subject Namespace at the Protocol Layer","description":"","frontmatter":{},"headers":[],"relativePath":"adr/008-subject-namespace-validation.md","filePath":"adr/008-subject-namespace-validation.md","lastUpdated":1768070912000}'),l={name:"adr/008-subject-namespace-validation.md"};function p(h,e,g,u,m,b){const o=r("CopyOrDownloadAsMarkdownButtons");return s(),n("div",null,[e[0]||(e[0]=t("div",{style:{display:"none"},hidden:"true","aria-hidden":"true"},"Are you an LLM? You can read better optimized documentation at /adr/008-subject-namespace-validation.md for this page in Markdown format",-1)),e[1]||(e[1]=t("h1",{id:"adr-008-enforce-reserved-subject-namespace-at-the-protocol-layer",tabindex:"-1"},[i("ADR 008: Enforce Reserved Subject Namespace at the Protocol Layer "),t("a",{class:"header-anchor",href:"#adr-008-enforce-reserved-subject-namespace-at-the-protocol-layer","aria-label":"Permalink to “ADR 008: Enforce Reserved Subject Namespace at the Protocol Layer”"},"​")],-1)),c(o),e[2]||(e[2]=d('<ul><li><strong>Date</strong>: 2025-11-23</li><li><strong>Status</strong>: Accepted</li><li><strong>Applies to</strong>: SBP</li><li><strong>Tags</strong>: protocol, validation, correctness, conformance</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>ADR-006 mandates that all <code>MessageFrame.subject</code> values start with one of four reserved prefixes: <code>rpc/</code>, <code>event/</code>, <code>stream/</code>, or <code>app/</code>.</p><p>The protocol layer did not enforce this contract. The wire codec accepted any string; validation only existed in <code>@sideband/rpc</code> (optional). This violated ADR-006 and the principle of correctness-first design.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Move subject validation into <code>@sideband/protocol</code> — the only package owning the wire-format contract.</p><ol><li><p><strong>Add branded <code>Subject</code> type</strong>: Prevents accidental misuse at the TypeScript level.</p></li><li><p><strong>Add <code>asSubject()</code> validator</strong>: Runtime validation enforcing:</p><ul><li>1–256 UTF-8 bytes (measured correctly, not code units)</li><li>Reserved prefix (<code>rpc/</code>, <code>event/</code>, <code>stream/</code>, or <code>app/</code>)</li><li>No null bytes or empty strings</li><li>Throws <code>ProtocolError(ProtocolViolation)</code> on violation</li></ul></li><li><p><strong>Update <code>MessageFrame.subject</code></strong>: Change from <code>string</code> to <code>Subject</code> type.</p></li><li><p><strong>Add <code>createMessageFrame()</code> factory</strong>: User-facing API that validates subject at construction.</p></li><li><p><strong>Update <code>decodeFrame()</code></strong>: Validate subject on wire decode. Invalid subjects → fatal protocol violation → connection close.</p></li><li><p><strong>Update RPC layer</strong>: Re-export protocol validator as <code>asRpcSubject()</code>. Remove duplicate validation. Keep <code>ProtocolViolation</code> class for backwards compatibility (extends <code>ProtocolError</code>).</p></li></ol><h2 id="technical-details" tabindex="-1">Technical Details <a class="header-anchor" href="#technical-details" aria-label="Permalink to “Technical Details”">​</a></h2><p><strong>UTF-8 byte length</strong>: Validator measures via <code>TextEncoder</code> (not JavaScript <code>.length</code>, which counts code units). Correctly handles multi-byte characters.</p><p><strong>Prefix list extensibility</strong>: Stored as const array, enabling future extensions (e.g., <code>signal/</code>) without API breakage. Update <code>RESERVED_SUBJECT_PREFIXES</code>, release minor version.</p><p><strong>Error semantics</strong>: Invalid subjects are fatal. On send: synchronous throw. On receive: <code>ProtocolError(ProtocolViolation)</code> → <code>ErrorFrame</code> → close connection.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Impact</th></tr></thead><tbody><tr><td><strong>Correctness</strong></td><td>Every frame on the wire provably conforms to ADR-006. No bypass paths.</td></tr><tr><td><strong>API safety</strong></td><td>Invalid subjects rejected at construction time, not silently sent or received.</td></tr><tr><td><strong>Breaking change</strong></td><td>Pre-1.0 acceptable. Raw <code>MessageFrame</code> construction will fail type-check or throw.</td></tr><tr><td><strong>Performance</strong></td><td>Negligible: one <code>TextEncoder</code> + prefix check per message.</td></tr></tbody></table><h2 id="alternatives-considered-and-rejected" tabindex="-1">Alternatives Considered and Rejected <a class="header-anchor" href="#alternatives-considered-and-rejected" aria-label="Permalink to “Alternatives Considered and Rejected”">​</a></h2><ul><li><strong>Validate only in RPC</strong>: Higher layers bypass; transports/tools emit invalid frames.</li><li><strong>Validate only on send</strong>: Malicious peers can flood with invalid subjects (DoS).</li><li><strong>Validate only on decode</strong>: Invalid frames constructed internally; bugs in middlewares.</li><li><strong>Configurable prefix set</strong>: Foot-gun; violates &quot;one obvious way&quot; principle.</li></ul>',15))])}const y=a(l,[["render",p]]);export{f as __pageData,y as default};
